import { describe, expect, it } from 'vitest';
import { inverseNormalCdf, normalCdf, normalPdf } from '../src/utils/normal.js';
import reference from './fixtures/normal-reference.json' with { type: 'json' };

/**
 * Every expected value comes from `fixtures/normal-reference.json`, which is generated by exact
 * BigInt fixed-point arithmetic at adaptive precision (see `fixtures/generate-reference.mjs`).
 * The fixtures are ground truth, not expectations recorded from this implementation.
 *
 * NEVER relax a tolerance in this file to make a change pass. If an assertion starts failing,
 * the implementation got less accurate.
 */

/** Relative error, which is the meaningful measure for tail probabilities. */
function relativeError(actual: number, expected: number): number {
  if (expected === 0) return actual === 0 ? 0 : Number.POSITIVE_INFINITY;
  return Math.abs(actual - expected) / Math.abs(expected);
}

function expectRelative(actual: number, expected: number, tolerance: number): void {
  const error = relativeError(actual, expected);
  expect(
    error,
    `relative error ${error.toExponential(3)} exceeds ${tolerance.toExponential(3)} ` +
      `(actual ${actual}, expected ${expected})`,
  ).toBeLessThanOrEqual(tolerance);
}

describe('normalPdf', () => {
  it('matches 40-digit ground truth at every fixture point', () => {
    for (const { x, value } of reference.pdf) {
      expectRelative(normalPdf(Number(x)), Number(value), 1e-15);
    }
  });

  it('is exactly symmetric', () => {
    for (const x of [0.1, 0.5, 1, 1.96, 3, 7.5, 12]) {
      expect(normalPdf(-x)).toBe(normalPdf(x));
    }
  });

  it('underflows to zero only beyond the representable range', () => {
    expect(normalPdf(37)).toBeGreaterThan(0);
    expect(normalPdf(50)).toBe(0);
  });

  it('rejects NaN', () => {
    expect(() => normalPdf(Number.NaN)).toThrow(/NaN/i);
  });
});

describe('normalCdf', () => {
  it('is exactly 0.5 at zero', () => {
    expect(normalCdf(0)).toBe(0.5);
  });

  it('matches 40-digit ground truth across the body of the distribution', () => {
    // |x| <= 3 is Hart's rational branch. Its worst measured relative error is 1.2e-14, just
    // below the branch point, where the value itself is of order 1e-3.
    for (const { x, value } of reference.cdf) {
      if (Math.abs(Number(x)) > 3) continue;
      expectRelative(normalCdf(Number(x)), Number(value), 2e-14);
    }
  });

  it('keeps relative accuracy in the tail, not merely absolute accuracy', () => {
    // |x| > 3 is the deepened continued fraction. This is the assertion that West's published
    // 5-level form fails: it is off by 8.7e-9 at x = -8.
    for (const { x, value } of reference.cdf) {
      if (Math.abs(Number(x)) <= 3) continue;
      expectRelative(normalCdf(Number(x)), Number(value), 1e-15);
    }
  });

  it('is accurate where deep out-of-the-money options actually live', () => {
    // A weekly deep-OTM contract puts d2 around -4.6; this is the branch that reaches.
    const truth = reference.cdf.find((entry) => entry.x === '-4.6');
    expect(truth, 'fixture for x = -4.6 is missing').toBeDefined();
    expectRelative(normalCdf(-4.6), Number(truth?.value), 1e-15);
  });

  it('saturates to exactly 0 and 1 far outside the representable range', () => {
    expect(normalCdf(-40)).toBe(0);
    expect(normalCdf(40)).toBe(1);
  });

  it('satisfies the reflection N(x) + N(-x) = 1 to machine precision', () => {
    // Structural identity, not an accuracy claim: it holds whatever the algorithm's own
    // accuracy is, because both branches are computed from the same upper-tail routine. Put-call
    // parity depends on this and on nothing else.
    const grid = [
      0, 1e-8, 1e-4, 0.01, 0.1, 0.25, 0.5, 0.75, 1, 1.5, 1.96, 2.5, 2.999, 3, 3.001, 4, 4.6, 5, 6,
      7, 7.07106781186547, 8, 10, 15, 20, 30, 36.9,
    ];
    for (const x of grid) {
      const sum = normalCdf(x) + normalCdf(-x);
      expect(Math.abs(sum - 1), `N(${x}) + N(-${x}) = ${sum}`).toBeLessThanOrEqual(
        2 * Number.EPSILON,
      );
    }
  });

  it('is continuous across the branch point', () => {
    // A step at the branch would show up as a discontinuity in any Greek computed by finite
    // differences. The test is that the central difference straddling the branch reproduces the
    // density there — comparing N on either side to N at the branch would only measure the
    // slope, which is not zero and not a defect.
    // h is 1e-5, not something smaller: on the upper side N is close to 1, so a tighter step
    // would lose the difference to cancellation long before it improved the truncation error.
    for (const centre of [-3, 3]) {
      const h = 1e-5;
      const slope = (normalCdf(centre + h) - normalCdf(centre - h)) / (2 * h);
      expectRelative(slope, normalPdf(centre), 1e-7);
    }
  });

  it('is monotonically non-decreasing', () => {
    let previous = normalCdf(-12);
    for (let x = -12; x <= 12; x += 0.005) {
      const current = normalCdf(x);
      expect(current, `not monotone at x = ${x}`).toBeGreaterThanOrEqual(previous);
      previous = current;
    }
  });

  it('stays inside [0, 1]', () => {
    for (let x = -12; x <= 12; x += 0.05) {
      const value = normalCdf(x);
      expect(value).toBeGreaterThanOrEqual(0);
      expect(value).toBeLessThanOrEqual(1);
    }
  });

  it('rejects NaN', () => {
    expect(() => normalCdf(Number.NaN)).toThrow(/NaN/i);
  });
});

describe('inverseNormalCdf', () => {
  it('is exactly zero at p = 0.5', () => {
    expect(inverseNormalCdf(0.5)).toBe(0);
  });

  it('matches 40-digit ground truth at every fixture quantile', () => {
    for (const { p, value } of reference.quantile) {
      if (Number(p) === 0.5) continue;
      expectRelative(inverseNormalCdf(Number(p)), Number(value), 1e-14);
    }
  });

  it('round-trips against normalCdf, to the accuracy the round trip can carry', () => {
    // Round-tripping through p is limited by how finely p itself can be represented, not by the
    // quantile function: dx/dp = 1/phi(x), so an unavoidable rounding of p by one ulp moves x by
    // eps/phi(x). At x = 6 that is already 1.8e-8. Asserting a fixed tolerance here would be
    // asserting something about floating point, not about this implementation.
    for (let x = -6; x <= 6; x += 0.25) {
      const p = normalCdf(x);
      if (p <= 0 || p >= 1) continue;
      const budget = Math.max((4 * Number.EPSILON) / normalPdf(x), 1e-12);
      expect(
        Math.abs(inverseNormalCdf(p) - x),
        `round trip at x = ${x} (budget ${budget.toExponential(2)})`,
      ).toBeLessThanOrEqual(budget);
    }
  });

  it('round-trips in the lower tail, where p stays relatively well resolved', () => {
    // Below zero p is small, so it carries full relative precision and the round trip is far
    // better conditioned than it is on the upper side.
    for (const x of [-7, -8, -9, -10, -15, -20]) {
      expect(inverseNormalCdf(normalCdf(x)), `round trip at x = ${x}`).toBeCloseTo(x, 9);
    }
  });

  it('is antisymmetric to machine precision', () => {
    // p is kept away from 0 and 1: representing 1 - p there loses the precision this asserts,
    // which is a property of binary floating point, not of the quantile function.
    for (const p of [1e-4, 0.01, 0.2, 0.4, 0.49]) {
      expect(inverseNormalCdf(p) + inverseNormalCdf(1 - p)).toBeCloseTo(0, 9);
    }
  });

  it('rejects probabilities outside (0, 1)', () => {
    expect(() => inverseNormalCdf(0)).toThrow(/probability/i);
    expect(() => inverseNormalCdf(1)).toThrow(/probability/i);
    expect(() => inverseNormalCdf(-0.1)).toThrow(/probability/i);
    expect(() => inverseNormalCdf(1.1)).toThrow(/probability/i);
    expect(() => inverseNormalCdf(Number.NaN)).toThrow(/probability/i);
  });
});
